<script setup lang="ts">
import { ArrowLeftOutlined, LeftOutlined, RightOutlined, SendOutlined, UploadOutlined, HistoryOutlined, DatabaseOutlined, DownloadOutlined, ThunderboltOutlined, EditOutlined, BulbOutlined, CodeOutlined } from '@ant-design/icons-vue'
import type { Problem, ProblemSummary, Submission, Job } from '../../../shared/types'
const id=String(useRoute().params.id)
const {data:p,refresh,error}=await useFetch<Problem>('/api/problems/'+id)
const {data:catalog}=await useFetch<ProblemSummary[]>('/api/problems')
const {data:history,refresh:refreshHistory}=await useFetch<Submission[]>('/api/submissions')
const {data:jobs,refresh:refreshJobs}=await useFetch<Job[]>('/api/jobs')
const index=computed(()=>catalog.value?.findIndex(x=>x.id===id)??-1)
const previous=computed(()=>catalog.value?.[index.value-1]),next=computed(()=>catalog.value?.[index.value+1])
const records=computed(()=>(history.value||[]).filter(s=>s.problemId===id))
const submitOpen=ref(false),draft=reactive({mips:''}),submitting=ref(false),submitError=ref(''),filename=ref(''),nonce=ref('')
const latest=ref<Submission|null>(null),resultOpen=ref(false),dataOpen=ref(false),historyOpen=ref(false),hintOpen=ref(false)
const job=ref<Job|null>(jobs.value?.find(j=>j.problemId===id)||null),generating=computed(()=>!!job.value&&['queued','running'].includes(job.value.state))
const generationCount=ref(6),actionError=ref(''),manualOpen=ref(false),manualJson=ref(''),manualError=ref(''),savingCases=ref(false)
const hasForbiddenDirective=computed(()=>draft.mips.split('\n').some(line=>/^\s*\.(?:globl|global)\s+.*\bmain\b/i.test(line.split('#')[0]!)))
const isPending=computed(()=>latest.value&&['Running','Queued'].includes(latest.value.verdict))
let timer:ReturnType<typeof setInterval>|undefined,saveTimer:ReturnType<typeof setTimeout>|undefined,ready=false,polling=false
function message(e:any){return e.data?.statusMessage||e.message||'请求失败，请重试。'}
function saveDraft(){if(!ready)return;try{localStorage.setItem('mips-lab-draft-'+id,JSON.stringify(draft))}catch{submitError.value='浏览器存储已满，请保存源码文件。'}}
async function restoreLatest(){try{const pending=JSON.parse(localStorage.getItem('mips-lab-request-'+id)||'null');const s=records.value.find(s=>s.id===pending?.id)||records.value.find(s=>['Queued','Running'].includes(s.verdict));if(s){latest.value=await $fetch<Submission>('/api/submissions/'+s.id,{timeout:4000});if(s.id===pending?.id){submitOpen.value=false;resultOpen.value=true;nonce.value='';localStorage.removeItem('mips-lab-request-'+id)}}}catch{/* Retry when the connection returns. */}}
function reconnect(){void refresh();void refreshHistory().then(restoreLatest);void refreshJobs().then(async()=>{const summary=jobs.value?.find(j=>j.problemId===id);job.value=summary?await $fetch<Job>('/api/jobs/'+summary.id):null});void poll()}
onMounted(()=>{try{const d=JSON.parse(localStorage.getItem('mips-lab-draft-'+id)||'null');if(d){if(typeof d.mips==='string')draft.mips=d.mips}const pending=JSON.parse(localStorage.getItem('mips-lab-request-'+id)||'null');if(pending&&pending.language==='mips'&&pending.code===draft.mips)nonce.value=pending.id}catch{}ready=true;if(job.value)void $fetch<Job>('/api/jobs/'+job.value.id).then(value=>job.value=value).catch(()=>{});restoreLatest();timer=setInterval(poll,1500);window.addEventListener('mips-lab-reconnected',reconnect);window.addEventListener('beforeunload',saveDraft)})
watch(draft,()=>{nonce.value='';clearTimeout(saveTimer);saveTimer=setTimeout(saveDraft,300)},{deep:true})
onBeforeUnmount(()=>{clearInterval(timer);clearTimeout(saveTimer);saveDraft();window.removeEventListener('mips-lab-reconnected',reconnect);window.removeEventListener('beforeunload',saveDraft)})
async function poll(){if(polling)return;polling=true;try{if(latest.value&&['Queued','Running'].includes(latest.value.verdict)){latest.value=await $fetch<Submission>('/api/submissions/'+latest.value.id,{timeout:4000});if(!['Queued','Running'].includes(latest.value.verdict))await refreshHistory()}if(job.value&&['queued','running'].includes(job.value.state)){job.value=await $fetch<Job>('/api/jobs/'+job.value.id,{timeout:4000});if(job.value.state==='done')await refresh()}}catch{/* Connection indicator handles retries; keep the last known task ID. */}finally{polling=false}}
async function submit(){if(hasForbiddenDirective.value)return;submitting.value=true;submitError.value='';saveDraft();try{const pending=JSON.parse(localStorage.getItem('mips-lab-request-'+id)||'null');nonce.value=pending&&pending.language==='mips'&&pending.code===draft.mips?pending.id:crypto.randomUUID()}catch{nonce.value=crypto.randomUUID()}try{localStorage.setItem('mips-lab-request-'+id,JSON.stringify({id:nonce.value,language:'mips',code:draft.mips}));latest.value=await $fetch<Submission>('/api/submissions',{method:'POST',timeout:10000,body:{requestId:nonce.value,problemId:id,language:'mips',code:draft.mips}});submitOpen.value=false;resultOpen.value=true;nonce.value='';localStorage.removeItem('mips-lab-request-'+id);await refreshHistory()}catch(e){submitError.value=message(e)}finally{submitting.value=false}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>65536){submitError.value='源码文件不能超过 64 KiB。';return}if(!/\.(asm|s|mips)$/i.test(file.name)){submitError.value='支持 .asm、.s 或 .mips 文件。';return}draft.mips=await file.text();filename.value=file.name;submitError.value=''}
async function viewRecord(sid:string){latest.value=await $fetch<Submission>('/api/submissions/'+sid);resultOpen.value=true}
async function generate(){actionError.value='';try{job.value=await $fetch<Job>('/api/generate/'+id,{method:'POST',body:{count:generationCount.value}})}catch(e){actionError.value=message(e)}}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(p.value?.cases,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=id+'-cases.json';a.click();URL.revokeObjectURL(url)}
function editData(){manualJson.value=JSON.stringify(p.value?.cases.map(c=>({input:c.input,output:c.output,label:c.label})),null,2);manualError.value='';manualOpen.value=true}
async function saveCases(){savingCases.value=true;manualError.value='';try{let cases;try{cases=JSON.parse(manualJson.value)}catch{throw new Error('请输入合法的 JSON 数组。')}await $fetch('/api/problems/'+id+'/cases',{method:'PUT',body:{cases}});await refresh();manualOpen.value=false}catch(e){manualError.value=message(e)}finally{savingCases.value=false}}
</script>
<template><div v-if="p" class="page problem-page">
 <NuxtLink to="/" class="back-link"><ArrowLeftOutlined/>返回题库</NuxtLink>
 <div class="problem-page-heading"><div><div class="problem-eyebrow"><span class="mono">{{p.id}}</span><span :class="['difficulty',p.difficulty==='入门'?'easy':p.difficulty==='基础'?'basic':'medium']">{{p.difficulty}}</span><span>{{p.source}}</span></div><h1>{{p.title}}</h1><div class="problem-topic-tags"><span v-for="tag in p.tags" :key="tag">{{tag}}</span></div></div><a-button type="primary" size="large" @click="submitError='';submitOpen=true"><template #icon><SendOutlined/></template>提交代码</a-button></div>
 <div v-if="latest" class="last-submission"><VerdictBadge :value="latest.verdict"/><span>{{latest.language==='c'?'C11（历史）':'MIPS'}} · {{latest.passed}} / {{latest.total}} 通过</span><button class="text-button" @click="viewRecord(latest.id)">查看评测详情 →</button></div>
 <article class="statement-card"><div class="statement-card-meta"><span>时限 {{p.timeLimit/1000}} 秒</span><span>MIPS 指令上限 {{p.stepLimit/1000000}}M</span><div><button @click="dataOpen=true"><DatabaseOutlined/>测试数据 · {{p.cases.length}}</button><button @click="historyOpen=true"><HistoryOutlined/>提交记录</button></div></div>
 <div class="statement-body"><a-alert v-if="p.verification==='仅样例'||!p.cases.length" type="warning" show-icon :message="p.cases.length?'仅含公开样例':'请先添加测试数据'"/>
 <h2>题目描述</h2><MarkdownText :text="p.description"/>
 <h2>输入格式</h2><MarkdownText :text="p.inputFormat"/>
 <p v-if="p.source==='洛谷'&&p.generation" class="field-note">题面展示洛谷原始格式。模型生成的纯数字数据可按每行一个数字评测，实际格式见「测试数据」。</p>
 <h2>输出格式</h2><MarkdownText :text="p.outputFormat"/>
 <template v-for="(sample,i) in p.samples" :key="i"><h2>样例 {{i+1}}</h2><div class="statement-sample"><div><div class="io-label">输入</div><pre>{{sample.input}}</pre></div><div><div class="io-label">输出</div><pre>{{sample.output}}</pre></div></div></template>
 <template v-if="p.constraints"><h2>数据范围</h2><MarkdownText :text="p.constraints"/></template>
 <section v-if="p.cExample" class="c-example"><h2>C 代码示例</h2><pre><code>{{p.cExample}}</code></pre></section>
 <div class="problem-rules"><CodeOutlined/><span>关闭延迟槽 · 禁用 <code>.globl main</code></span></div>
 <div class="statement-bottom"><button class="text-button" @click="hintOpen=!hintOpen"><BulbOutlined/>{{hintOpen?'收起提示':'查看提示'}}</button><a v-if="p.sourceUrl" :href="p.sourceUrl" target="_blank" rel="noopener noreferrer">查看洛谷原题 ↗</a></div><div v-if="hintOpen" class="hint-box">{{p.hint}}</div>
 </div></article><nav class="problem-navigation" aria-label="相邻题目"><NuxtLink v-if="previous" :to="'/problems/'+previous.id"><LeftOutlined/><span>上一题<small>{{previous.title}}</small></span></NuxtLink><span v-else/><NuxtLink v-if="next" :to="'/problems/'+next.id"><span>下一题<small>{{next.title}}</small></span><RightOutlined/></NuxtLink></nav>
 <a-modal v-model:open="submitOpen" title="提交代码" :footer="null" :width="700"><div class="submit-dialog"><div class="submit-language"><strong>MIPS</strong><label class="upload-source"><UploadOutlined/>上传源码<input type="file" accept=".asm,.s,.mips" @change="upload"/></label></div><p v-if="filename" class="field-note">已载入 {{filename}}</p><a-alert v-if="hasForbiddenDirective" type="error" show-icon message="请删除 .globl main 声明。"/><label for="submission-source" class="source-label">源码</label><a-textarea id="submission-source" v-model:value="draft.mips" :rows="14" placeholder="粘贴源码，或上传本地文件" class="submission-source" :spellcheck="false"/><a-alert v-if="submitError" type="error" show-icon :message="submitError"/><div class="submit-dialog-footer"><span>最大 64 KiB · 草稿自动保存</span><a-button type="primary" :loading="submitting" :disabled="!draft.mips.trim()||hasForbiddenDirective||!p.cases.length" @click="submit"><template #icon><SendOutlined/></template>提交评测</a-button></div></div></a-modal>
 <a-drawer v-model:open="resultOpen" title="评测结果" :width="680"><SubmissionResult v-if="latest" :submission="latest"/></a-drawer>
 <a-drawer v-model:open="historyOpen" title="本题提交记录" :width="620"><a-empty v-if="!records.length" description="还没有提交记录"/><button v-for="s in records" :key="s.id" class="history-item" @click="viewRecord(s.id)"><VerdictBadge :value="s.verdict"/><span>{{s.language==='c'?'C11（历史）':'MIPS'}}</span><span>{{s.score}} 分</span><span>{{new Date(s.createdAt).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}}</span></button></a-drawer>
 <a-drawer v-model:open="dataOpen" title="测试数据" :width="680"><a-alert v-if="actionError" type="error" :message="actionError" show-icon/><div class="generation-box"><strong><ThunderboltOutlined/>模型生成数据</strong><p>生成后替换当前测试集。</p><div class="generation-actions"><a-input-number v-model:value="generationCount" :min="1" :max="8" aria-label="数据组数"/><a-button type="primary" :loading="generating" @click="generate">生成数据</a-button><a-button @click="editData"><EditOutlined/>手动编辑</a-button></div></div><GenerationStatus v-if="job" :job="job"/><p class="field-note">数据来源：{{p.verification}}<template v-if="p.generation"> · {{p.generation.model}}<br>{{p.generation.notes}}</template></p><a-collapse :bordered="false"><a-collapse-panel v-for="(c,i) in p.cases" :key="i" :header="`#${i+1} · ${c.label}`"><div class="data-preview"><div class="io-label">输入</div><pre>{{c.input}}</pre><div class="io-label">标准输出</div><pre>{{c.output}}</pre></div></a-collapse-panel></a-collapse><a-button v-if="p.cases.length" class="export-button" @click="download"><DownloadOutlined/>导出数据</a-button></a-drawer>
 <a-modal v-model:open="manualOpen" title="编辑测试数据" ok-text="保存" cancel-text="取消" :confirm-loading="savingCases" :width="740" @ok="saveCases"><p class="field-note">JSON 数组，每项包含 input、output、label；保存会替换当前测试集。</p><a-alert v-if="manualError" type="error" :message="manualError"/><a-textarea v-model:value="manualJson" :rows="16" class="mono" aria-label="测试数据 JSON"/></a-modal>
</div><div v-else class="page"><a-result status="404" title="题目加载失败" :sub-title="error?.message"><template #extra><a-button @click="refresh()">重试</a-button><NuxtLink to="/">返回题库</NuxtLink></template></a-result></div></template>
